-- Step 1: Add UNIQUE constraint for upsert support
ALTER TABLE delivery_sites DROP CONSTRAINT IF EXISTS delivery_sites_company_site_code_unique;
ALTER TABLE delivery_sites ADD CONSTRAINT delivery_sites_company_site_code_unique UNIQUE (company_id, site_code);

